public static Pcm decode(byte[] ogg) throws IOException {
        InputStream input = new ByteArrayInputStream(ogg);
        ByteArrayOutputStream out = new ByteArrayOutputStream(
                (int) Math.max(64, Math.min((long) ogg.length * 4, 1 << 26)));   // cap initial guess at 64 MiB

        SyncState oy = new SyncState();
        StreamState os = new StreamState();
        Page og = new Page();
        Packet op = new Packet();
        Info vi = new Info();
        Comment vc = new Comment();
        DspState vd = new DspState();
        Block vb = new Block(vd);

        try {
        byte[] buffer;
        int bytes;
        oy.init();

        // ---- first page / first header packet ----
        int index = oy.buffer(4096);
        buffer = oy.data;
        bytes = readSome(input, buffer, index, 4096);
        oy.wrote(bytes);

        if(oy.pageout(og) != 1)
            throw new IOException("not an Ogg bitstream");

        os.init(og.serialno());
        vi.init();
        vc.init();
        if(os.pagein(og) < 0)
            throw new IOException("error reading first Ogg page");
        if(os.packetout(op) != 1)
            throw new IOException("error reading initial header packet");
        if(vi.synthesis_headerin(vc, op) < 0)
            throw new IOException("not Vorbis audio data");

        // ---- remaining two header packets ----
        int i = 0;
        while(i < 2) {
            while(i < 2) {
                int result = oy.pageout(og);
                if(result == 0)
                    break;
                if(result == 1) {
                    os.pagein(og);
                    while(i < 2) {
                        result = os.packetout(op);
                        if(result == 0)
                            break;
                        if(result == -1 || vi.synthesis_headerin(vc, op) < 0)
                            throw new IOException("corrupt secondary Vorbis header");
                        i++;
                    }
                }
            }
            index = oy.buffer(4096);
            buffer = oy.data;
            bytes = readSome(input, buffer, index, 4096);
            if(bytes == 0 && i < 2)
                throw new IOException("end of file before all Vorbis headers");
            oy.wrote(bytes);
        }

        int rate = vi.rate;
        int channels = vi.channels;
        if(channels < 1 || rate < 1)
            throw new IOException("invalid Vorbis stream (rate=" + rate + ", channels=" + channels + ")");

        int convsize = 4096 / channels;
        byte[] convbuffer = new byte[convsize * 2 * channels];

        vd.synthesis_init(vi);
        vb.init(vd);

        float[][][] pcmf = new float[1][][];
        int[] pcmIndex = new int[channels];

        boolean eos = false;
        while(!eos) {
            while(!eos) {
                int result = oy.pageout(og);
                if(result == 0)
                    break;          // need more data
                if(result != -1) {  // -1 == hole in data; skip but keep going
                    os.pagein(og);
                    while(true) {
                        result = os.packetout(op);
                        if(result == 0)
                            break;
                        if(result == -1)
                            continue;
                        if(vb.synthesis(op) == 0)
                            vd.synthesis_blockin(vb);
                        int samples;
                        while((samples = vd.synthesis_pcmout(pcmf, pcmIndex)) > 0) {
                            float[][] pcm = pcmf[0];
                            int bout = Math.min(samples, convsize);
                            for(int ch = 0; ch < channels; ch++) {
                                int ptr = ch * 2;
                                int mono = pcmIndex[ch];
                                for(int j = 0; j < bout; j++) {
                                    int val = (int) (pcm[ch][mono + j] * 32767.0);
                                    if(val > 32767)  val = 32767;
                                    if(val < -32768) val = -32768;
                                    if(val < 0)      val = val | 0x8000;
                                    convbuffer[ptr] = (byte) val;
                                    convbuffer[ptr + 1] = (byte) (val >>> 8);
                                    ptr += 2 * channels;
                                }
                            }
                            out.write(convbuffer, 0, 2 * channels * bout);
                            vd.synthesis_read(bout);
                        }
                    }
                    if(og.eos() != 0)
                        eos = true;
                }
            }
            if(!eos) {
                index = oy.buffer(4096);
                buffer = oy.data;
                bytes = readSome(input, buffer, index, 4096);
                oy.wrote(bytes);
                if(bytes == 0)
                    eos = true;
            }
        }

        return new Pcm(out.toByteArray(), rate, channels);
        } finally {
            os.clear();
            vb.clear();
            vd.clear();
            vi.clear();
            oy.clear();
        }
    }

public static String summary(Layer l) {
        try {
            switch(l.name) {
                case "image": {
                    ImageInfo ii = ImageInfo.parse(l.data);
                    String fmt = ii.imageFormat != null ? ii.imageFormat : "image";
                    return ii.recognized ? "id=" + ii.id + "  " + fmt : fmt;
                }
                case "tex": {
                    TexInfo ti = TexInfo.parse(l.data);
                    if(!ti.found)
                        return "texture";
                    return (ti.recognized ? "id=" + ti.id + "  " : "")
                            + ti.szX + "x" + ti.szY + " " + ti.imageFormat;
                }
                case "audio2": {
                    AudioInfo ai = AudioInfo.parse(l.data);
                    if(ai.format == null)
                        return "audio";
                    return (ai.recognized && !ai.id.isEmpty() ? "\"" + ai.id + "\" " : "") + "Ogg Vorbis";
                }
                case "font": {
                    FontInfo fi = FontInfo.parse(l.data);
                    return fi.format != null ? fi.format.toUpperCase() + " font" : "font";
                }
                case "tooltip":
                case "pagina": {
                    String text = editableText(l);
                    return text != null
                            ? "\"" + preview(text, 30) + "\""
                            : "invalid UTF-8 (raw)";
                }
                case "action": {
                    java.util.Map<String, Object> m = ActionCodec.decode(l.data);
                    return "\"" + m.get("name") + "\"";
                }
                case "props": {
                    java.util.Map<String, Object> m = PropsCodec.decode(l.data);
                    @SuppressWarnings("unchecked")
                    java.util.Map<String, Object> p = (java.util.Map<String, Object>) m.get("props");
                    return p.size() + " propert" + (p.size() == 1 ? "y" : "ies");
                }
                case "vbuf2": {
                    Vbuf2Info vi = Vbuf2Info.parse(l.data);
                    return vi.recognized ? vi.num + " vertices" : "vertex buffer";
                }
                case "mesh": {
                    MeshInfo mi = MeshInfo.parse(l.data);
                    return mi.recognized ? mi.numTris + " triangles" : "mesh";
                }
                case "tile": {
                    TileInfo ti = TileInfo.parse(l.data);
                    if(!ti.recognized)
                        return "terrain tile";
                    return ti.kindName() + " id=" + ti.id
                            + (ti.imageFormat != null ? " " + ti.imageFormat : "");
                }
                case "tileset2": {
                    TilesetInfo ti = TilesetInfo.parse(l.data);
                    if(!ti.recognized)
                        return "tileset";
                    return "tiler \"" + (ti.tilerName != null ? ti.tilerName : "?") + "\""
                            + (ti.flavors.isEmpty() ? "" : ", " + ti.flavors.size() + " flavor");
                }
                case "flavobj": {
                    FlavObjInfo fo = FlavObjInfo.parse(l.data);
                    return fo.recognized ? fo.res : "flavor object";
                }
                case "mat2": {
                    java.util.Map<String, Object> m = Mat2Codec.decode(l.data);
                    java.util.List<?> es = (java.util.List<?>) m.get("entries");
                    return es.size() + " material command" + (es.size() == 1 ? "" : "s");
                }
                case "code": {
                    CodeInfo ci = CodeInfo.parse(l.data);
                    if(!ci.recognized)
                        return "code";
                    int dot = ci.name.lastIndexOf('.');
                    return (dot >= 0 ? ci.name.substring(dot + 1) : ci.name) + ".class";
                }
                case "anim": {
                    java.util.Map<String, Object> m = AnimCodec.decode(l.data);
                    java.util.List<?> fr = (java.util.List<?>) m.get("frames");
                    return fr.size() + " frames @ " + m.get("delay") + "ms";
                }
                case "neg": {
                    java.util.Map<String, Object> m = NegCodec.decode(l.data);
                    java.util.List<?> c = (java.util.List<?>) m.get("center");
                    java.util.List<?> eps = (java.util.List<?>) m.get("endpoints");
                    return "click (" + c.get(0) + "," + c.get(1) + "), " + eps.size() + " endpoint grp";
                }
                case "obst": {
                    java.util.Map<String, Object> m = ObstCodec.decode(l.data);
                    java.util.List<?> polys = (java.util.List<?>) m.get("polygons");
                    int pts = 0;
                    for(Object p : polys)
                        pts += ((java.util.List<?>) p).size();
                    return polys.size() + " polygon" + (polys.size() == 1 ? "" : "s") + ", " + pts + " pts";
                }
                case "codeentry": {
                    CodeEntryInfo ce = CodeEntryInfo.parse(l.data);
                    return ce.entries.size() + " entry pt" + (ce.entries.size() == 1 ? "" : "s")
                            + ", " + ce.classpath.size() + " dep" + (ce.classpath.size() == 1 ? "" : "s");
                }
                case "deps": {
                    DepsInfo di = DepsInfo.parse(l.data);
                    if(!di.recognized)
                        return "dependencies";
                    return di.deps.size() + " dependenc" + (di.deps.size() == 1 ? "y" : "ies");
                }
                case "rlink": {
                    RLinkInfo ri = RLinkInfo.parse(l.data);
                    if(!ri.recognized && ri.links.isEmpty())
                        return "resource links";
                    return ri.links.size() + " link" + (ri.links.size() == 1 ? "" : "s");
                }
                case "src": {
                    SrcInfo si = SrcInfo.parse(l.data);
                    return si.recognized ? si.fileName : "source file";
                }
                case "light": {
                    LightInfo li = LightInfo.parse(l.data);
                    return li.recognized ? li.kind() : "light";
                }
                case "skel": {
                    SkelInfo si = SkelInfo.parse(l.data);
                    if(!si.recognized)
                        return "skeleton";
                    return si.bones.size() + " bone" + (si.bones.size() == 1 ? "" : "s");
                }
                case "skan": {
                    SkanInfo si = SkanInfo.parse(l.data);
                    if(!si.recognized)
                        return "animation";
                    return si.tracks.size() + " track" + (si.tracks.size() == 1 ? "" : "s")
                            + ", " + trim(si.len) + "s " + si.mode;
                }
                case "boneoff": {
                    BoneOffInfo bo = BoneOffInfo.parse(l.data);
                    if(!bo.recognized)
                        return "equip point";
                    return "\"" + bo.name + "\"  " + bo.ops.size() + " op" + (bo.ops.size() == 1 ? "" : "s");
                }
                case "manim": {
                    MeshAnimInfo mi = MeshAnimInfo.parse(l.data);
                    if(!mi.recognized)
                        return "mesh animation";
                    return mi.frames.size() + " frame" + (mi.frames.size() == 1 ? "" : "s")
                            + ", " + trim(mi.len) + "s";
                }
                default:
                    return l.data.length + " bytes";
            }
        } catch(RuntimeException e) {
            return l.data.length + " bytes";
        }
    }

